import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`vs-gemini`,hasInputUrl:!1,heroTitle:`From Search Engine to Work Engine`,heroSubtitle:`Perplexity Computer orchestrates 19 AI models — including Gemini 3.1 Pro, GPT-5.5, and Claude Opus 4.6 — picking the right one for each subtask across multi-hour workflows.`,heroOverlaySteps:[`Analyzing your workflow requirements and task complexity`,`Matching each task to the optimal model`,`Spinning up specialized sub-agents in a sandboxed cloud environment`,`Multi-model workflow orchestrated and executing — ready to deliver`],generatingSteps:[`Evaluating your task to determine the right models`,`Designing an agent to orchestrate sub-agents across 19 specialized AI models`,`Configuring sandboxed cloud execution with persistent memory and enterprise connectors`,`Setting up multi-step workflow with automatic model routing and deliverable packaging`],featureSectionTitle:`From one prompt to a multi-model workflow`,featureCardTitles:[`Connects to your entire stack`,`Outputs you can ship`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Drive, Gmail, Slack, Notion, GitHub, Airtable, Shopify — Computer plugs into your tools so workflows run end-to-end without copy-pasting between apps.`,`Research reports. Data analyses. Code deployments. Content calendars. Competitive audits. Computer delivers finished work — not chat replies.`],capabilitySectionTitle:`Your AI workforce, on autopilot`,capabilitySectionSubtitle:`Describe what you need, step away, come back to finished deliverables.`,capabilityCards:[{title:`Multi-Model Orchestration`,description:`Computer can route tasks across GPT, Claude Sonnet, Opus, Gemini Pro and more — picking the best model for research, coding, writing, and analysis.`},{title:`Autonomous Sub-Agents`,description:`Computer can spawn specialized sub-agents that work in parallel — one researching, one coding, one writing — then merge their outputs into a single deliverable.`},{title:`Sandboxed Cloud Execution`,description:`Computer can run multi-hour workflows in a secure cloud sandbox — browsing the web, executing code, and generating files without touching your local machine.`},{title:`Connect Your Tools`,description:`Computer can read and write to Google Drive, Notion, Slack, GitHub, Google Sheets, Airtable, and more — build workflows across your entire stack.`},{title:`Persistent Memory`,description:`Computer can remember your preferences, past projects, and context across sessions — so every workflow builds on what it already knows about your work.`},{title:`Monitor & Alert`,description:`Computer can run recurring workflows on a schedule and alert you when results change — competitors shift, data updates, or new opportunities appear.`}]});export{t as default};
